<template>
  <section class="weekly-plan">
    <div class="toolbar"><label>週開始日<input v-model="startDate" type="date" @change="loadPlan" /></label><span>後工程計画をLT日数だけ前倒しして算出。TK=1号機、AJ=2号機。</span><button class="btn" @click="showSettings = !showSettings">対象設定</button><button class="btn" @click="saveManualQuantities">手回数を保存</button><button class="btn" @click="openPrintDialog">印刷</button><button class="btn primary" @click="loadPlan">再計算</button></div>
    <div v-if="showPrintDialog" class="print-modal" @click.self="showPrintDialog = false"><section class="print-dialog"><h3>合計表を印刷</h3><div class="print-date-fields"><label>開始日<input v-model="printStartDate" type="date" /></label><label>終了日<input v-model="printEndDate" type="date" /></label></div><div class="print-actions"><button class="btn primary" @click="printSummary">印刷</button><button class="btn" @click="showPrintDialog = false">キャンセル</button></div></section></div>
    <p v-if="message">{{ message }}</p>
    <div v-if="showSettings" class="settings"><h3>週間計画対象設定</h3><div class="form"><label>後工程ライン<select v-model="form.downstream_line" @change="onDownstreamLineChange"><option :value="null">選択</option><option v-for="x in lines" :key="x.id" :value="x.id">{{ x.line_code }} {{ x.line_name }}</option></select></label><label>後工程製品番号<select v-model="form.product" :disabled="!form.downstream_line"><option :value="null">{{ form.downstream_line ? '選択' : '先に後工程ラインを選択' }}</option><option v-for="x in downstreamProducts" :key="x.id" :value="x.id">{{ x.product_code }} {{ x.product_name }}</option></select></label><label>レーザ完成品番号<select v-model="form.finished_product" @change="selectAllPatterns"><option :value="null">選択</option><option v-for="x in laserFinishedProducts" :key="x.id" :value="x.id">{{ x.product_code }} {{ x.product_name }}</option></select></label><label>レーザパターン<select v-model="selectedPatternIds" multiple :disabled="!form.finished_product"><option v-for="x in filteredPatterns" :key="x.id" :value="x.id">{{ x.pattern_no }}</option></select></label><label>後工程数量取得元<select v-model="form.quantity_source"><option value="ORDER_QTY">後工程需要（order_qty）</option><option value="PLAN_QTY">後工程計画（plan_qty）</option></select></label><label>LT(日)<input v-model.number="form.lead_time_days" min="0" type="number" /></label><button class="btn primary" @click="saveTarget">{{ form.id ? '更新' : '追加' }}</button><button class="btn" @click="reset">クリア</button></div><table><thead><tr><th>後工程ライン</th><th>後工程製品</th><th>パターン</th><th>レーザ完成品</th><th>取得元</th><th>LT</th><th></th></tr></thead><tbody><tr v-for="x in targets" :key="x.id"><td>{{ x.downstream_line_name }}</td><td>{{ x.product_code }} {{ x.product_name }}</td><td>{{ x.pattern_no }}</td><td>{{ x.finished_product_code }}</td><td>{{ x.quantity_source === 'PLAN_QTY' ? '後工程計画' : '後工程需要' }}</td><td>{{ x.lead_time_days }}</td><td><button @click="edit(x)">編集</button><button @click="remove(x)">削除</button></td></tr></tbody></table></div>
    <div class="grid"><table class="plan-table"><colgroup><col v-for="(width, index) in fixedColumnWidths" :key="`fixed-${index}`" :style="{ width }" /><template v-for="week in weekGroups" :key="`columns-${week.key}`"><template v-for="day in week.days" :key="`columns-${day}`"><col class="demand-column" /><col class="automatic-column" /><col class="manual-column" /></template><col class="week-total-column" /><col class="week-total-column" /><col class="week-total-column" /></template></colgroup><thead><tr><th v-for="column in fixedColumns" :key="column" rowspan="3">{{ column }}</th><template v-for="week in weekGroups" :key="`dates-${week.key}`"><th v-for="day in week.days" :key="day" colspan="3">{{ day.slice(5) }}</th><th class="week-total" colspan="3">週合計</th></template></tr><tr><template v-for="week in weekGroups" :key="`totals-${week.key}`"><th v-for="day in week.days" :key="`total-${day}`" colspan="3">1号 {{ hours(day, 'TK') }}h / 2号 {{ hours(day, 'AJ') }}h</th><th class="week-total" colspan="3">1号 {{ weeklyHours(week, 'TK') }}h / 2号 {{ weeklyHours(week, 'AJ') }}h</th></template></tr><tr><template v-for="week in weekGroups" :key="`labels-${week.key}`"><template v-for="day in week.days" :key="`labels-${day}`"><th>需要</th><th>自回数</th><th>手回数</th></template><th class="week-total">需要</th><th class="week-total">自回数</th><th class="week-total">手回数</th></template></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="`product-group-${productGroup(row.product_code)}`"><td>{{ row.downstream_line_name }}</td><td>{{ row.product_code }}</td><td>{{ row.pattern_no }}</td><td>{{ number(row.take_qty, 0) }}</td><td>{{ number(row.thickness, 1) }}</td><td>{{ row.machine === 'TK' ? '1号' : '2号' }}</td><td>{{ number(row.hours_per_sheet, 2) }}</td><td>{{ row.lead_time_days }}</td><template v-for="week in weekGroups" :key="`${row.id}-${week.key}`"><template v-for="day in week.days" :key="`${row.id}-${day}`"><td>{{ number(dailyValue(row, day, 'demand_qty'), 0) }}</td><td :class="{ 'smaller-val': isSmallerValue(dailyValue(row, day, 'automatic_sheets'), dailyValue(row, day, 'manual_sheets')) }">{{ dailyValue(row, day, 'automatic_sheets') }}</td><td :class="{ 'smaller-val': isSmallerValue(dailyValue(row, day, 'manual_sheets'), dailyValue(row, day, 'automatic_sheets')) }">{{ dailyValue(row, day, 'manual_sheets') }}</td></template><td class="week-total">{{ number(weeklyValue(row, week, 'demand_qty'), 0) }}</td><td class="week-total" :class="{ 'smaller-val': isSmallerValue(weeklyValue(row, week, 'automatic_sheets'), weeklyValue(row, week, 'manual_sheets')) }">{{ weeklyValue(row, week, 'automatic_sheets') }}</td><td class="week-total" :class="{ 'smaller-val': isSmallerValue(weeklyValue(row, week, 'manual_sheets'), weeklyValue(row, week, 'automatic_sheets')) }">{{ weeklyValue(row, week, 'manual_sheets') }}</td></template></tr><tr v-if="!rows.length"><td :colspan="gridColumnCount">対象設定を追加してください。</td></tr></tbody></table></div>
    <section class="pattern-summary-grid"><h3>レーザ加工計画（パターン別合計）</h3><div class="pattern-summary-scroll"><table class="pattern-summary-table"><colgroup><col v-for="(width, index) in summaryColumnWidths" :key="`summary-fixed-${index}`" :style="{ width }" /><template v-for="week in weekGroups" :key="`summary-columns-${week.key}`"><template v-for="day in week.days" :key="`summary-columns-${day}`"><col class="demand-column" /><col class="automatic-column" /><col class="manual-column" /></template><col class="week-total-column" /><col class="week-total-column" /><col class="week-total-column" /></template></colgroup><thead><tr><th v-for="column in summaryColumns" :key="column" rowspan="3">{{ column }}</th><template v-for="week in weekGroups" :key="`summary-dates-${week.key}`"><th v-for="day in week.days" :key="`summary-date-${day}`" colspan="3">{{ day.slice(5) }}</th><th class="week-total" colspan="3">週合計</th></template></tr><tr><template v-for="week in weekGroups" :key="`summary-totals-${week.key}`"><th v-for="day in week.days" :key="`summary-total-${day}`" colspan="3">1号 {{ hours(day, 'TK') }}h / 2号 {{ hours(day, 'AJ') }}h</th><th class="week-total" colspan="3">1号 {{ weeklyHours(week, 'TK') }}h / 2号 {{ weeklyHours(week, 'AJ') }}h</th></template></tr><tr><template v-for="week in weekGroups" :key="`summary-labels-${week.key}`"><template v-for="day in week.days" :key="`summary-label-${day}`"><th>需要</th><th>自回数</th><th>手回数</th></template><th class="week-total">需要</th><th class="week-total">自回数</th><th class="week-total">手回数</th></template></tr></thead><tbody><tr v-for="pattern in patternRows" :key="pattern.pattern_no" :class="`summary-product-${summaryProductGroup(pattern.representative_product_code)}`"><td>{{ pattern.downstream_line_names.join(' / ') }}</td><td>{{ pattern.representative_product_code }}</td><td>{{ pattern.pattern_no }}</td><td>{{ pattern.take_qtys.map((qty) => number(qty, 0)).join(' / ') }}</td><td>{{ number(pattern.thickness, 1) }}</td><td>{{ pattern.machine === 'TK' ? '1号' : '2号' }}</td><td>{{ number(pattern.hours_per_sheet, 2) }}</td><td>{{ pattern.lead_time_days.join(' / ') }}</td><template v-for="week in weekGroups" :key="`${pattern.pattern_no}-${week.key}`"><template v-for="day in week.days" :key="`${pattern.pattern_no}-${day}`"><td>{{ number(patternDailyValue(pattern, day, 'demand_qty'), 0) }}</td><td :class="{ 'smaller-val': isSmallerValue(patternDailyValue(pattern, day, 'automatic_sheets'), patternDailyValue(pattern, day, 'manual_sheets')) }">{{ patternDailyValue(pattern, day, 'automatic_sheets') }}</td><td :class="{ 'smaller-val': isSmallerValue(patternDailyValue(pattern, day, 'manual_sheets'), patternDailyValue(pattern, day, 'automatic_sheets')) }"><input class="manual-sheets" v-model.number="pattern.daily[day].manual_sheets" min="0" step="1" type="number" /></td></template><td class="week-total">{{ number(patternWeeklyValue(pattern, week, 'demand_qty'), 0) }}</td><td class="week-total" :class="{ 'smaller-val': isSmallerValue(patternWeeklyValue(pattern, week, 'automatic_sheets'), patternWeeklyValue(pattern, week, 'manual_sheets')) }">{{ patternWeeklyValue(pattern, week, 'automatic_sheets') }}</td><td class="week-total" :class="{ 'smaller-val': isSmallerValue(patternWeeklyValue(pattern, week, 'manual_sheets'), patternWeeklyValue(pattern, week, 'automatic_sheets')) }">{{ patternWeeklyValue(pattern, week, 'manual_sheets') }}</td></template></tr><tr v-if="!patternRows.length"><td :colspan="gridColumnCount">対象設定を追加してください。</td></tr></tbody></table></div></section>
    <section class="material-grid"><h3>日別材料必要枚数</h3><table class="material-table"><thead><tr><th>材料コード</th><th>材料名</th><th>板厚</th><th v-for="day in days" :key="`material-${day}`">{{ day.slice(5) }}</th></tr></thead><tbody><tr v-for="material in materialRows" :key="material.material_id"><td>{{ material.material_code }}</td><td>{{ material.material_name }}</td><td>{{ number(material.thickness, 1) }}</td><td v-for="day in days" :key="`${material.material_id}-${day}`">{{ number(material.daily[day] ?? 0, 0) }}</td></tr><tr v-if="!materialRows.length"><td :colspan="3 + days.length">材料対象の週間計画がありません。</td></tr></tbody></table></section>
  </section>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import api from '@/api/client'
const iso = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
const monday = (value = new Date()) => { const d = new Date(value); d.setDate(d.getDate() - ((d.getDay()+6)%7)); return iso(d) }
const tomorrow = () => { const d = new Date(); d.setDate(d.getDate() + 1); return iso(d) }
const startDate = ref(monday()), rows = ref([]), patternRows = ref([]), materialRows = ref([]), targets = ref([]), lines = ref([]), products = ref([]), patterns = ref([]), downstreamProducts = ref([]), message = ref(''), showSettings = ref(false), showPrintDialog = ref(false), printStartDate = ref(tomorrow()), printEndDate = ref(tomorrow()), changedManualQuantities = ref({})
const fixedColumns = ['後工程', '製品番号', '代称', '取', '板厚', '設備', 'h/枚', 'LT']
const fixedColumnWidths = ['68px', '94px', '38px', '32px', '36px', '36px', '42px', '28px']
const summaryColumns = ['後工程', '製品番号', '代称', '取', '板厚', '設備', 'h/枚', 'LT']
const summaryColumnWidths = ['68px', '94px', '38px', '32px', '36px', '36px', '42px', '28px']
const productGroups = computed(() => {
  const groups = new Map()
  rows.value.forEach((row) => {
    if (!groups.has(row.product_code)) groups.set(row.product_code, groups.size % 2)
  })
  return groups
})
const productGroup = (productCode) => productGroups.value.get(productCode) || 0
const summaryProductGroups = computed(() => {
  const groups = new Map()
  patternRows.value.forEach((pattern) => {
    if (!groups.has(pattern.representative_product_code)) groups.set(pattern.representative_product_code, groups.size % 2)
  })
  return groups
})
const summaryProductGroup = (productCode) => summaryProductGroups.value.get(productCode) || 0
const empty = () => ({ id:null, downstream_line:null, product:null, laser_pattern:null, finished_product:null, lead_time_days:0, quantity_source:'ORDER_QTY', sort_order:0, is_active:true })
const form = ref(empty())
const selectedPatternIds = ref([])
const loadDownstreamProducts = async () => {
  if (!form.value.downstream_line) { downstreamProducts.value = []; return }
  const { data } = await api.laserWeeklyPlans.getDownstreamProducts(form.value.downstream_line)
  downstreamProducts.value = data || []
}
const onDownstreamLineChange = async () => {
  form.value.product = null
  form.value.finished_product = null
  selectedPatternIds.value = []
  try { await loadDownstreamProducts() } catch (e) { message.value = '後工程製品を取得できませんでした。' }
}
const laserFinishedProducts = computed(() => {
  const ids = new Set(patterns.value.flatMap((pattern) =>
    (pattern.finished_items || []).map((item) => Number(item.finished_product)),
  ))
  const downstream = products.value.find((product) => Number(product.id) === Number(form.value.product))
  const baseCode = String(downstream?.product_code || '').replace(/[kKｋＫcCｃＣ]+$/, '')
  return products.value
    .filter((product) => ids.has(Number(product.id)))
    .sort((a, b) => {
      const aMatch = baseCode && String(a.product_code || '') === baseCode ? 0 : 1
      const bMatch = baseCode && String(b.product_code || '') === baseCode ? 0 : 1
      if (aMatch !== bMatch) return aMatch - bMatch
      return String(a.product_code || '').localeCompare(String(b.product_code || ''), 'ja', { numeric: true })
    })
})
const filteredPatterns = computed(() => patterns.value.filter((pattern) =>
  (pattern.finished_items || []).some((item) => Number(item.finished_product) === Number(form.value.finished_product)),
))
const selectAllPatterns = () => {
  selectedPatternIds.value = filteredPatterns.value.map((pattern) => pattern.id)
}
const days = computed(() => { const d = new Date(`${startDate.value}T00:00:00`), out=[]; for(let i=0;i<14;i++){const x=new Date(d);x.setDate(d.getDate()+i);if(x.getDay()>0&&x.getDay()<6)out.push(iso(x))} return out })
const number = (value, digits) => {
  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed.toFixed(digits) : ''
}
const dailyValue = (row, day, field) => row.daily[day]?.[field] ?? 0
const isManualDifferent = (row, day) => Number(dailyValue(row, day, 'automatic_sheets')) !== Number(dailyValue(row, day, 'manual_sheets'))
const patternDailyValue = (pattern, day, field) => pattern.daily[day]?.[field] ?? 0
const isPatternManualDifferent = (pattern, day) => Number(patternDailyValue(pattern, day, 'automatic_sheets')) !== Number(patternDailyValue(pattern, day, 'manual_sheets'))
const isSmallerValue = (a, b) => { const na = Number(a), nb = Number(b); return na !== nb && na < nb }
const hours = (day, machine) => { const sum=patternRows.value.filter(x=>x.machine===machine).reduce((n,x)=>n+Number(patternDailyValue(x, day, 'manual_sheets'))*Number(x.hours_per_sheet||0),0); return sum.toFixed(2).replace(/\.00$/,'') }
const weekGroups = computed(() => { const allDays = days.value, groups = []; for (let i = 0; i < allDays.length; i += 5) { const w = allDays.slice(i, i + 5); if (w.length) groups.push({ key: w[0], days: w }) } return groups })
const weeklyValue = (row, week, field) => week.days.reduce((s, day) => s + Number(dailyValue(row, day, field)), 0)
const weeklyHours = (week, machine) => { const sum = patternRows.value.filter(x => x.machine === machine).reduce((n, x) => n + week.days.reduce((s, day) => s + Number(patternDailyValue(x, day, 'manual_sheets')) * Number(x.hours_per_sheet || 0), 0), 0); return sum.toFixed(2).replace(/\.00$/, '') }
const patternWeeklyValue = (pattern, week, field) => week.days.reduce((s, day) => s + Number(patternDailyValue(pattern, day, field)), 0)
const isWeeklyManualDifferent = (row, week) => weeklyValue(row, week, 'automatic_sheets') !== weeklyValue(row, week, 'manual_sheets')
const isPatternWeeklyManualDifferent = (pattern, week) => patternWeeklyValue(pattern, week, 'automatic_sheets') !== patternWeeklyValue(pattern, week, 'manual_sheets')
const gridColumnCount = computed(() => fixedColumns.length + days.value.length * 3 + weekGroups.value.length * 3)
const openPrintDialog = () => { const date = tomorrow(); printStartDate.value = date; printEndDate.value = date; showPrintDialog.value = true }
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[char])
const printNumber = (value, digits = 0) => Number(value || 0).toLocaleString('ja-JP', { minimumFractionDigits: digits, maximumFractionDigits: digits })
const printSummary = async () => {
  if (!printStartDate.value || !printEndDate.value || printEndDate.value < printStartDate.value) { message.value = '印刷期間を正しく指定してください。'; return }
  const printWindow = window.open('', '_blank')
  if (!printWindow) { message.value = '印刷画面を開けませんでした。ポップアップを許可してください。'; return }
  try {
    const { data } = await api.laserWeeklyPlans.getWeeklyPlan({ start_date: printStartDate.value, end_date: printEndDate.value })
    const printDays = data.dates || []
    const patternsForPrint = data.pattern_rows || []
    const machineHours = (day, machine) => patternsForPrint.filter((pattern) => pattern.machine === machine).reduce((sum, pattern) => sum + Number(pattern.daily[day]?.manual_sheets || 0) * Number(pattern.hours_per_sheet || 0), 0)
    const dailyCells = (pattern) => printDays.map((day) => { const daily = pattern.daily[day] || {}; return `<td>${printNumber(daily.demand_qty)}</td><td>${printNumber(daily.automatic_sheets)}</td><td>${printNumber(daily.manual_sheets)}</td>` }).join('')
    const rowsHtml = patternsForPrint.map((pattern) => `<tr><td>${escapeHtml(pattern.downstream_line_names.join(' / '))}</td><td>${escapeHtml(pattern.representative_product_code)}</td><td>${escapeHtml(pattern.pattern_no)}</td><td>${escapeHtml(pattern.take_qtys.map((qty) => printNumber(qty)).join(' / '))}</td><td>${printNumber(pattern.thickness, 1)}</td><td>${pattern.machine === 'TK' ? '1号' : '2号'}</td><td>${printNumber(pattern.hours_per_sheet, 2)}</td><td>${escapeHtml(pattern.lead_time_days.join(' / '))}</td>${dailyCells(pattern)}</tr>`).join('') || `<tr><td colspan="${8 + printDays.length * 3}">対象設定を追加してください。</td></tr>`
    printWindow.document.write(`<!doctype html><html lang="ja"><head><meta charset="utf-8"><title>レーザ加工計画（パターン別合計）</title><style>@page{size:landscape;margin:10mm}body{font-family:Meiryo,sans-serif;color:#111827}h1{font-size:16px;margin:0 0 5px}.period{font-size:12px;margin:0 0 10px}table{border-collapse:collapse;font-size:9px;width:100%}th,td{border:1px solid #94a3b8;padding:3px;white-space:nowrap;text-align:right}th{background:#e2e8f0}td:nth-child(-n+2){text-align:left}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><h1>レーザ加工計画（パターン別合計）</h1><p class="period">期間: ${escapeHtml(printStartDate.value)} ～ ${escapeHtml(printEndDate.value)}</p><table><thead><tr><th rowspan="3">後工程</th><th rowspan="3">製品番号</th><th rowspan="3">代称</th><th rowspan="3">取</th><th rowspan="3">板厚</th><th rowspan="3">設備</th><th rowspan="3">h/枚</th><th rowspan="3">LT</th>${printDays.map((day) => `<th colspan="3">${escapeHtml(day.slice(5))}</th>`).join('')}</tr><tr>${printDays.map((day) => `<th colspan="3">1号 ${printNumber(machineHours(day, 'TK'), 2)}h / 2号 ${printNumber(machineHours(day, 'AJ'), 2)}h</th>`).join('')}</tr><tr>${printDays.map(() => '<th>需要</th><th>自回数</th><th>手回数</th>').join('')}</tr></thead><tbody>${rowsHtml}</tbody></table></body></html>`)
    printWindow.document.close()
    printWindow.focus()
    printWindow.print()
    showPrintDialog.value = false
  } catch (e) {
    printWindow.close()
    message.value = e.response?.data?.detail || '印刷用の計画を取得できませんでした。'
  }
}
const markManualQuantity = (row, day) => { const sheets = Number(row.daily[day].manual_sheets); if (!Number.isInteger(sheets) || sheets < 0) { message.value = '手回数は0以上の整数で入力してください。'; return } changedManualQuantities.value = { ...changedManualQuantities.value, [`${row.id}:${day}`]: { target_id: row.id, plan_date: day, sheets } } }
const saveManualQuantities = async () => { try { const quantities = patternRows.value.flatMap((pattern) => days.value.map((day) => ({ laser_pattern_id: pattern.laser_pattern_id, plan_date: day, sheets: Number(patternDailyValue(pattern, day, 'manual_sheets')) }))); if (!quantities.length) return; await api.laserWeeklyPlans.savePatternManualQuantities(quantities); changedManualQuantities.value = {}; await loadPlan(); message.value = '手回数を保存しました。' } catch (e) { message.value = e.response?.data?.detail || '手回数を保存できませんでした。' } }
const loadPlan = async () => { startDate.value=monday(startDate.value); try { const {data}=await api.laserWeeklyPlans.getWeeklyPlan({start_date:startDate.value}); rows.value=data.rows||[]; patternRows.value=data.pattern_rows||[]; materialRows.value=data.material_rows||[]; changedManualQuantities.value={}; message.value='' } catch(e){message.value=e.response?.data?.detail||'計画を取得できませんでした。'} }
const loadMasters = async () => { const [t,l,p,lp]=await Promise.all([api.laserWeeklyPlans.getTargets(),api.lines.getLines({page_size:1000,line_type:'PROD',is_active:true}),api.products.getAllProducts(),api.laserPatterns.getLaserPatterns({page_size:1000})]); targets.value=t.data.results||t.data||[]; lines.value=l.data.results||l.data||[]; products.value=Array.isArray(p) ? p : (p.data?.results||p.data||[]); patterns.value=lp.data.results||lp.data||[] }
const reset=()=>{form.value=empty();selectedPatternIds.value=[];downstreamProducts.value=[]}; const edit=async x=>{form.value={...x};await loadDownstreamProducts();selectedPatternIds.value=[x.laser_pattern];showSettings.value=true}
const saveTarget=async()=>{try{const p={...form.value};delete p.id;if(form.value.id){p.laser_pattern=selectedPatternIds.value[0];await api.laserWeeklyPlans.updateTarget(form.value.id,p)}else{if(!selectedPatternIds.value.length){message.value='レーザパターンを1件以上選択してください。';return}await Promise.all(selectedPatternIds.value.map((laser_pattern)=>api.laserWeeklyPlans.createTarget({...p,laser_pattern})))}reset();await loadMasters();await loadPlan()}catch(e){message.value=e.response?.data?.product?.[0]||e.response?.data?.detail||'対象設定を保存できませんでした。'}}
const remove=async x=>{if(!confirm(`${x.pattern_no} を削除しますか？`))return;await api.laserWeeklyPlans.deleteTarget(x.id);await loadMasters();await loadPlan()}
onMounted(async()=>{await loadMasters();await loadPlan()})
